def test_search_sends_filters_beside_v1(httpx_mock, client):
    httpx_mock.add_response(json=envelope([CITATION], total=57, next_page=1))
    page = client.data_citations.search(
        object_id="https://doi.org/10.3886/ICPSR01132.V1",
        member_id=78,
        relation="references",
        from_created_date="2002",
        until_created_date="2003-01",
        rows=1,
    )
    request = httpx_mock.get_requests()[0]
    assert request.url.path == "/beta/datacitations"
    assert dict(request.url.params) == {
        "object-id": "10.3886/icpsr01132.v1",
        "member-id": "78",
        "relation": "references",
        "from-created-date": "2002",
        "until-created-date": "2003-01",
        "rows": "1",
        "mailto": "tester@example.org",
    }
    assert page.total == 57
    assert page.next_cursor == "1"
    assert page.page == 0
    citation = page.results[0]
    assert citation.relation == "references"
    assert citation.subject.member == "78"
    assert citation.object.registration_agency == "Crossref"
    assert citation.object.type == "dataset"


def test_iterate_follows_next_page_until_null(httpx_mock, client):
    second = dict(CITATION, relation="is-supplemented-by")
    httpx_mock.add_response(
        url=f"{ROUTE}?subject-id=10.1/x&rows=1000&page=0&mailto=tester%40example.org",
        json=envelope([CITATION], total=2, next_page=1),
    )
    httpx_mock.add_response(
        url=f"{ROUTE}?subject-id=10.1/x&rows=1000&page=1&mailto=tester%40example.org",
        json=envelope([second], total=2, next_page=None),
    )
    relations = [
        citation.relation
        for citation in client.data_citations.iterate(subject_id="10.1/X")
    ]
    assert relations == ["references", "is-supplemented-by"]
    assert len(httpx_mock.get_requests()) == 2


